import numpy as np
import pandas as pd


def sku_last_trade(fit_df):
    return fit_df.groupby("sku")["placed_at"].max()


def account_last_order(fit_df):
    return fit_df.groupby("account_id")["placed_at"].max()


def staleness(last_seen, fit_end):
    return (fit_end - last_seen).dt.days.astype("float64")


def add(df, sku_stale, account_stale, portfolio_stale):
    out = df.copy()
    out["f_sku_days_since_trade"] = out["sku"].map(sku_stale).fillna(portfolio_stale)
    out["f_account_days_since_order"] = out["account_id"].map(account_stale).fillna(-1.0)
    return out
"}

{"path": "src/riskscore/cadence.py", "content": """"How regularly the product trades and the account orders."""
import numpy as np
import pandas as pd


def sku_trade_days(fit_df):
    days = fit_df["placed_at"].dt.normalize()
    return days.groupby(fit_df["sku"]).nunique().astype("float64")


def account_gap(fit_df):
    def mean_gap(stamps):
        days = np.sort(stamps.dt.normalize().unique())
        if len(days) < 2:
            return np.nan
        return float(np.diff(days).astype("timedelta64[D]").astype("float64").mean())

    gaps = fit_df.groupby("account_id")["placed_at"].apply(mean_gap)
    portfolio = float(gaps.mean())
    return gaps, portfolio


def add(df, trade_days, gaps, portfolio_gap):
    out = df.copy()
    out["f_sku_trade_days"] = out["sku"].map(trade_days).fillna(0.0)
    out["f_account_order_gap"] = out["account_id"].map(gaps).fillna(portfolio_gap)
    return out
"}

{"path": "src/riskscore/dispersion.py", "content": """"How much a sku's price has moved around its own usual level.

Lines priced unusually for their own sku are the ones that get sent back.
"""
import numpy as np
import pandas as pd


def price_dispersion(fit_df):
    def mad(prices):
        return float((prices - prices.mean()).abs().mean())

    return fit_df.groupby("sku")["unit_price"].apply(mad)


def add(df, dispersion):
    out = df.copy()
    prior = float(dispersion.mean())
    out["f_sku_price_dispersion"] = out["sku"].map(dispersion).fillna(prior)
    return out
"}

