import numpy as np
import pandas as pd


def price_range(fit_df):
    grp = fit_df.groupby("sku")["unit_price"]
    return (grp.max() - grp.min()).astype("float64")


def add(df, spread):
    out = df.copy()
    prior = float(spread.mean())
    out["f_sku_price_range"] = out["sku"].map(spread).fillna(prior)
    return out
