{"path": "src/riskscore/encoders.py", "content": """"Categorical rate encoding, fitted on the fit window.
"""
import numpy as np
import pandas as pd


class RateEncoder(object):

    def __init__(self, column, smoothing):
        self.column = column
        self.smoothing = float(smoothing)
        self.rates_ = None
        self.prior_ = None

    def fit(self, df, label):
        self.prior_ = float(df[label].mean())
        grp = df.groupby(self.column)[label]
        self.rates_ = ((grp.sum() + self.smoothing * self.prior_)
                       / (grp.size() + self.smoothing)).astype("float64")
        return self

    def transform(self, df):
        return df[self.column].map(self.rates_).fillna(self.prior_)


def fit_all(fit_df, columns, smoothing, label):
    return {column: RateEncoder(column, smoothing).fit(fit_df, label)
            for column in columns}


def apply_all(df, encoders):
    out = df.copy()
    for column, encoder in encoders.items():
        out["f_rate_%s" % column] = encoder.transform(out)
    return out
"}

